import java.util.*;

class Solution {
    public int equilibriumIndex(int[] nums) {
        Map<Integer, Integer> firstIndex = new HashMap<>();
        firstIndex.put(0, -1);
        int sum = 0, best = -1;
        for (int i = 0; i < nums.length; i++) {
            sum += nums[i];
            if (firstIndex.containsKey(sum)) {
                best = Math.max(best, i - firstIndex.get(sum));
            } else {
                firstIndex.put(sum, i);
            }
        }
        return best;
    }
}
